// kittyThemeIDs is filled in init via sortKittyThemeIDs.
var kittyThemeIDs []string

func init() {
	kittyThemeIDs = make([]string, 0, len(kittyThemes))
	for id := range kittyThemes {
		kittyThemeIDs = append(kittyThemeIDs, id)
	}
	sortKittyThemeIDs()
}
